<template><view class="page"><text class="eyebrow">TAIPING TONG 2.0</text><text class="h1">{{title}}</text><text class="muted intro">{{subtitle}}</text><TpCard class="main-card"><view class="metric" v-if="metric">{{metric}}</view><text class="card-title">{{headline}}</text><text class="body">{{body}}</text><view class="button" @click="submit">{{done ? '已完成 · 返回首页' : action}}</view></TpCard><TpCard v-for="item in items" :key="item" class="list-item"><text class="dot">•</text><text>{{item}}</text></TpCard></view></template><script setup lang="ts">import {ref} from 'vue';import TpCard from './TpCard.vue';defineProps<{title:string;subtitle:string;headline:string;body:string;action:string;items:string[];metric?:string}>();const done=ref(false);const submit=()=>{done.value=true;uni.showToast({title:'演示操作已完成',icon:'success'});setTimeout(()=>uni.navigateBack(),700)}</script><style scoped lang="scss">@import '@/styles/theme.scss';.h1,.intro{display:block;margin-top:14rpx}.intro{margin-bottom:30rpx}.main-card{background:linear-gradient(140deg,#ffffffdd,#e5e2ffdd)}.metric{font-size:72rpx;font-weight:700;color:#554fc2;margin-bottom:18rpx}.card-title{display:block;font-size:34rpx;font-weight:700}.body{display:block;color:#6d7198;font-size:27rpx;line-height:1.7;margin:14rpx 0 28rpx}.list-item{display:flex;align-items:center;margin-top:16rpx;font-size:28rpx}.dot{font-size:38rpx;color:#6d62f1;margin-right:14rpx}</style>
